import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:]))

    ans = 0
    j = 0

    for i in range(n):
        while j < n and a[j] < 2 * a[i]:
            j += 1
        ans += n - j

    print(ans)

if __name__ == "__main__":
    solve()
